#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int current_floor = 0;
    int destination_floor = 0;
    int i;
    for (i = 1; i < argc; i++) {
        destination_floor = atoi(argv[i]);
        if (destination_floor < 0) {
            printf("INVALID_FLOOR\n");
            continue;
        }
        if (current_floor < destination_floor) {
            while (current_floor < destination_floor) {
                current_floor++;
                printf("MOVE_UP %d->%d\n", current_floor - 1, current_floor);
            }
        } else if (current_floor > destination_floor) {
            while (current_floor > destination_floor) {
                current_floor--;
                printf("MOVE_DOWN %d->%d\n", current_floor + 1, current_floor);
            }
        }
        printf("ARRIVE %d\n", current_floor);
        printf("DOORS_OPEN\n");
        printf("DOORS_CLOSE\n");
    }
    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
